#include <Servo.h>

Servo servoX;
Servo servoY;

const int joyX = A0;
const int joyY = A1;

void setup() {
  servoX.attach(9);
  servoY.attach(10);
}

void loop() {
  int valX = analogRead(joyX);
  int valY = analogRead(joyY);

  // Преобразуем значения джойстика (0-1023) в углы поворота серво (0-180)
  int posX = map(valX, 0, 1023, 0, 180);
  int posY = map(valY, 0, 1023, 0, 180);

  servoX.write(posX);
  servoY.write(posY);

  delay(15); // Стабилизация
}
